Value.Calculation:
Let ( [
  ~data = JSONGetElement ( $param ; "startDate" )
; ~year = GetValue ( Substitute ( ~data ; "-" ; ¶ ) ; 1 )
; ~month = GetValue ( Substitute ( ~data ; "-" ; ¶ ) ; 2 )
; ~day = GetValue ( Substitute ( ~data ; "-" ; ¶ ) ; 3 )
] ;
Date ( ~month ; ~day ; ~year )
)

Let ( [
  ~data = JSONGetElement ( $param ; "endDate" )
; ~year = GetValue ( Substitute ( ~data ; "-" ; ¶ ) ; 1 )
; ~month = GetValue ( Substitute ( ~data ; "-" ; ¶ ) ; 2 )
; ~day = GetValue ( Substitute ( ~data ; "-" ; ¶ ) ; 3 )
] ;
Date ( ~month ; ~day ; ~year )
)
